WITH flattened_attrs AS (SELECT id, log_ts, level, status_code, context, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, SIZE(context) AS num_context, SHIFTRIGHT(status_code, 2) AS status_code_high, context['version'] AS version FROM app_logs) SELECT id, log_ts, level, status_code, context, user_id, num_context, status_code_high, version, CUME_DIST() OVER w_part AS num_context_cume_dist, AVG(status_code_high) OVER (PARTITION BY level ORDER BY num_context, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS status_code_high_avg_5_prior, LAST_VALUE(status_code_high, TRUE) OVER (PARTITION BY level ORDER BY num_context, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_status_code_high FROM flattened_attrs WINDOW w_part AS (PARTITION BY level ORDER BY num_context DESC);
